-- Rewords 15 questions where a careful student could defend a second answer, and fixes 7 small option slips
-- (a mislabelled region, a duplicate value, an overlapping option). Every answer key stays the same: each UPDATE
-- also matches on the current key. Explanations are updated to match the new wording.

UPDATE questions SET stem = 'Choose the correct form:
Were I ______ the post, I would refuse it.', options = '["offer", "to be offered", "offering", "to offer"]', why = '''Were I to be offered the post'' is the inverted, formal form of ''If I were to be offered the post'', used for an unlikely future situation. The person would receive the offer, so the passive infinitive ''to be offered'' is needed.', wrong = '{"0": "''Were I offer'' is ungrammatical, and the base form ''offer'' would make me the one doing the offering.", "2": "''Were I offering'' is active, so it would mean I am the one offering the post. It also does not complete the ''were ... to'' pattern.", "3": "''To offer'' is active, so it would mean I am the one offering the post, which changes the meaning."}', updated_at = unixepoch() * 1000 WHERE id = 'ENG-0584' AND answer = 1;
UPDATE questions SET stem = 'Which sentence is correct?', options = '["He is senior than me.", "He is senior to me.", "He is senior with me.", "He is senior from me."]', why = 'Some comparatives from Latin, such as senior, junior, superior, inferior and prior, are followed by to, not than. So "He is senior to me" is correct. A memory hook: Latin -ior words take to.', wrong = '{"0": "Senior is followed by to, not than. \"Senior than\" is a common error.", "2": "\"Senior with\" is incorrect. Senior always takes the fixed preposition to.", "3": "\"Senior from\" is incorrect. The fixed preposition is to."}', updated_at = unixepoch() * 1000 WHERE id = 'ENG-0283' AND answer = 1;
UPDATE questions SET stem = 'Choose the correct indirect form of:
He said to me, "I will meet you here tomorrow."', options = '["He said that he will meet me here tomorrow.", "He said that he would meet me here tomorrow.", "He said that he would meet you there the next day.", "He said that he would meet me there the next day."]', why = 'After a past reporting verb, ''will'' becomes ''would'', ''here'' becomes ''there'' and ''tomorrow'' becomes ''the next day''. The speaker''s ''I'' becomes ''he'', and ''you'' means the listener, who is me, so it becomes ''me'': ''He said that he would meet me there the next day.''', wrong = '{"0": "Nothing has been changed: ''will'', ''here'' and ''tomorrow'' should become ''would'', ''there'' and ''the next day''.", "1": "''Will'' has changed to ''would'', but ''here'' and ''tomorrow'' are still unchanged. They should be ''there'' and ''the next day''.", "2": "The other changes are right, but ''you'' refers to the listener, who is me, so it should become ''me''."}', updated_at = unixepoch() * 1000 WHERE id = 'ENG-0437' AND answer = 3;
UPDATE questions SET stem = 'On average, how many hydrogen bonds can each water molecule form, according to the textbook?', options = '["2", "1", "3", "8"]', why = 'The number of hydrogen bonds a molecule can form on average depends on both its number of H atoms on F, O or N and its number of lone pairs on those atoms. A water molecule has two hydrogen atoms and two lone pairs on oxygen, which match up evenly. So each water molecule forms two hydrogen bonds on average.', wrong = '{"1": "One hydrogen bond per molecule is the case for NH₃ (one lone pair) and HF (one hydrogen atom).", "2": "Three would need more matching hydrogen atoms and lone pairs than water has.", "3": "Eight is far more than water''s two hydrogen atoms and two lone pairs allow. Even counting every bond a molecule takes part in, the most is four, and shared bonds average two per molecule."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-0219' AND answer = 0;
UPDATE questions SET stem = 'In the titration of aqueous ammonia with HCl, the pH at the equivalence point is', options = '["exactly 7, so phenolphthalein is the only suitable indicator.", "less than 7 (about 5.3), so methyl orange or methyl red is suitable.", "greater than 7, so phenolphthalein is suitable.", "about 12, so no indicator works."]', why = 'At the equivalence point all the ammonia has become NH₄Cl. NH₄⁺, the conjugate acid of a weak base, releases H⁺ ions, so the pH is below 7, about 5.3. The steep jump in pH near equivalence lies in the acidic region, so indicators that change colour there, such as methyl orange or methyl red, are used for strong acid and weak base titrations.', wrong = '{"0": "The pH at equivalence is not 7, because NH₄⁺ makes the solution acidic. Phenolphthalein changes colour only in basic solution.", "2": "A pH above 7 at equivalence is typical of a weak acid and strong base titration, not this one.", "3": "The equivalence pH is acidic, about 5.3, not 12."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-0431' AND answer = 1;
UPDATE questions SET stem = 'Of these Period 3 elements, which forms the ion with the largest radius?', options = '["Sodium", "Magnesium", "Phosphorus", "Chlorine"]', why = 'P³⁻ and Cl⁻ both have 18 electrons. P³⁻ has only 15 protons pulling on them while Cl⁻ has 17, so the electron cloud of P³⁻ is held less tightly and spreads out further. Na⁺ has lost its whole outer shell and is very small, so P³⁻ is the largest of these ions.', wrong = '{"0": "Na⁺ has lost its outer shell and has only two shells left, so it is a small ion.", "1": "Mg²⁺ has lost its whole outer shell, like Na⁺, and has one more proton pulling on the same 10 electrons, so it is even smaller than Na⁺.", "3": "Cl⁻ has the same 18 electrons as P³⁻ but 2 more protons, so it is pulled in tighter and is smaller."}', updated_at = unixepoch() * 1000 WHERE id = 'CHE-9045' AND answer = 2;
UPDATE questions SET stem = 'Taking ΔW as the work done by the system, the first law of thermodynamics can be written as', options = '["ΔQ = ΔU + ΔW", "ΔQ = ΔU − ΔW", "ΔU = ΔQ + ΔW", "ΔW = ΔU + ΔQ"]', why = 'The first law of thermodynamics is energy conservation for heat and work. Heat supplied to a system goes partly into raising its internal energy and partly into work done by the system. So ΔQ = ΔU + ΔW, where ΔW is the work done by the system.', wrong = '{"1": "With ΔW as the work done by the system, it must be added to ΔU, not subtracted.", "2": "ΔU = ΔQ + ΔW would be correct only if ΔW meant work done on the system. Here ΔW is work done by the system, so ΔU = ΔQ − ΔW.", "3": "ΔW = ΔU + ΔQ is not a form of the first law. It adds heat and internal energy to get work."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-9024' AND answer = 0;
UPDATE questions SET stem = 'Using the book''s rounding rule, what is 27.65 rounded to three significant figures?', options = '["27.5", "27.6", "27.0", "28.0"]', why = 'To round 27.65 to three significant figures, the digit dropped is exactly 5. The book''s rule says that the previous digit is raised by one if it is odd and kept the same if it is even. The retained digit is 6, which is even, so it stays: 27.65 becomes 27.6.', wrong = '{"0": "Rounding never lowers the retained digit. The 6 can only stay as 6 or rise to 7.", "2": "27.0 drops the 6 as well as the 5. Only the last retained digit can change, and under this rule it stays 6.", "3": "28.0 changes the value by far too much. Only the last retained digit can change, and by at most one."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0479' AND answer = 1;
UPDATE questions SET stem = 'The vertebral column has how many vertebrae?', options = '["12", "24", "31", "33"]', why = 'The vertebral column has 33 vertebrae in five groups: 7 cervical, 12 thoracic, 5 lumbar, 5 sacral and 4 coccygeal. Check: 7 + 12 + 5 + 5 + 4 = 33. In adults the sacral and coccygeal vertebrae are fused.', wrong = '{"0": "12 is only the number of thoracic (rib-carrying) vertebrae.", "1": "24 is the number of ribs (12 pairs), not vertebrae.", "2": "31 is the number of pairs of spinal nerves that leave the spinal cord, not the number of vertebrae."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1491' AND answer = 3;
UPDATE questions SET stem = 'Lethal yellowing disease of coconuts is caused by', options = '["spiroplasmas", "rickettsias", "pseudomonads", "actinomycetes"]', why = 'Spiroplasmas, like mycoplasmas, are bacteria without cell walls. Spiroplasmas are important plant pathogens, and lethal yellowing of coconuts is the example of a plant disease given for this group.', wrong = '{"1": "Rickettsias are tiny bacteria that live inside animal cells and cause diseases such as typhus, spread by lice, ticks and fleas. They do not cause coconut disease.", "2": "Pseudomonads include many plant pathogens, but they are not the group named for lethal yellowing of coconuts.", "3": "Actinomycetes are filamentous bacteria linked with tuberculosis, leprosy and dental plaque, and are sources of antibiotics."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-0796' AND answer = 0;
UPDATE questions SET stem = 'Which joint disease is linked with a reduced amount of synovial fluid?', options = '["Osteoporosis", "Arthritis", "Rickets", "Sciatica"]', why = 'Synovial fluid is secreted by the synovial membrane and lubricates freely movable joints. In arthritis, especially osteoarthritis, the joint has less synovial fluid and the articular cartilage wears away. Bones rub together with more friction, causing pain and stiffness.', wrong = '{"0": "Osteoporosis is a loss of bone mass that makes bones thin and fragile. It affects the bone itself, not the synovial fluid of joints.", "2": "Rickets is softening of bones in children due to lack of vitamin D. It is not a joint disease.", "3": "Sciatica is pain along the sciatic nerve caused by pressure on it, often from a slipped disc."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9036' AND answer = 1;
UPDATE questions SET stem = 'Kidney stones mainly form because of', options = '["low filtration in Bowman''s capsule", "protein breakdown in the stomach", "high blood glucose", "a high level of calcium in the urine"]', why = 'About 70% of kidney stones are made of calcium oxalate, and others contain calcium phosphate. They form mainly when the urine carries too much calcium (hypercalciuria), so calcium salts crystallise in the kidney. Too much oxalate and too little water intake add to the risk.', wrong = '{"0": "A low rate of filtration in Bowman''s capsule is not the main cause of kidney stones.", "1": "Protein digestion in the stomach does not produce the crystals that form kidney stones.", "2": "High blood glucose is a sign of diabetes mellitus. It is not the main cause of kidney stones."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-9030' AND answer = 3;
UPDATE questions SET stem = 'A shop sells pens at one fixed price. Which of these facts are needed to find the price of one pen?
P: Ali paid Rs 150 in total.
Q: Ali bought 6 pens.
R: Ali bought pens and nothing else.
S: The pens are blue.', options = '["P and Q only", "P and R only", "P, Q and R", "Q and S only"]', why = 'Price of one pen = money spent on pens ÷ number of pens. P gives the total paid, Q gives the number of pens, and R confirms that the whole Rs 150 was spent on pens. All three are needed, and S (the colour) adds nothing. With all three, the price is 150 ÷ 6 = Rs 25.', wrong = '{"0": "P and Q alone are not enough: without R, part of the Rs 150 might have been spent on other items, so the price per pen is not certain.", "1": "Without Q the number of pens is unknown, so Rs 150 cannot be divided to find one pen''s price.", "3": "Neither Q nor S gives any amount of money, so no price can be found."}', updated_at = unixepoch() * 1000 WHERE id = 'MAT-0243' AND answer = 2;
UPDATE questions SET stem = 'Statement I: Schools in the city were closed for a week as temperatures crossed 47 °C.
Statement II: Hospitals reported many heatstroke cases.
What is the relationship between the two statements?', options = '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', why = 'Closing schools does not cause heatstroke, and heatstroke cases do not by themselves close schools. Both follow from the same extreme heat: temperatures above 47 °C made the schools close to protect children and sent many people to hospital with heatstroke. So both are effects of a common cause.', wrong = '{"0": "Closing schools does not cause people to get heatstroke.", "1": "Hospital cases do not by themselves close schools. The heat behind both is the cause.", "3": "They are linked through the extreme heat that caused both."}', updated_at = unixepoch() * 1000 WHERE id = 'LR-0208' AND answer = 2;
UPDATE questions SET stem = 'Statement I: Many students in the hostel developed diarrhoea.
Statement II: Several teachers who ate lunch at the hostel canteen that day also fell ill with diarrhoea.
What is the relationship between the two statements?', options = '["Statement I is the cause and Statement II is its effect", "Statement II is the cause and Statement I is its effect", "Both statements are effects of a common cause", "The two statements are not causally related"]', why = 'Students and teachers ate from the same hostel canteen, and both groups fell ill with the same illness at the same time. The most likely explanation is a shared source, such as contaminated food or water, that made both ill. So both are effects of a common cause.', wrong = '{"0": "Students passing the illness to teachers within a day is unlikely; both groups point to the same contaminated meal.", "1": "The teachers fell ill after eating at the canteen too, so they are another group affected, not the cause of the students'' illness.", "3": "Two groups who ate at the same place falling ill with the same illness on the same day are very likely linked."}', updated_at = unixepoch() * 1000 WHERE id = 'LR-0477' AND answer = 2;
UPDATE questions SET stem = 'What is the distance between the points (−2, 3) and (4, −5)?', options = '["14", "10", "2√5", "100"]', why = 'The distance formula is Pythagoras on the coordinate differences. Δx = 4 − (−2) = 6 and Δy = −5 − 3 = −8. Distance = √(6² + 8²) = √(36 + 64) = √100 = 10.', wrong = '{"0": "14 adds the differences 6 + 8. The straight-line distance uses √(6² + 8²).", "2": "2√5 = √20 would need coordinate differences of 2 and 4. The real differences are 6 and 8.", "3": "100 is 6² + 8², the step before taking the square root. The distance is √100 = 10."}', updated_at = unixepoch() * 1000 WHERE id = 'MAT-0370' AND answer = 1;
UPDATE questions SET stem = 'At what wavelength does a star of surface temperature 10 000 K radiate most strongly? (b = 2.9 × 10⁻³ m K)', options = '["290 nm, in the ultraviolet", "2.9 μm, in the infrared", "580 nm, in the visible", "29 nm, in the far ultraviolet"]', why = 'By Wien''s displacement law, λ_max = b ÷ T = 2.9 × 10⁻³ m K ÷ 10 000 K = 2.9 × 10⁻⁷ m = 290 nm. This is shorter than violet light (about 400 nm), so it lies in the ultraviolet. Very hot stars therefore look blue-white.', wrong = '{"1": "2.9 μm is ten times too long, a power-of-ten slip. It would be the peak of a star at only 1000 K.", "2": "580 nm is the peak for a star of 5000 K. Doubling T to 10 000 K halves λ_max to 290 nm.", "3": "29 nm is ten times too short, a power-of-ten slip. It would be the peak of a star at about 100 000 K."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0412' AND answer = 0;
UPDATE questions SET stem = 'The human body (about 310 K) emits radiation that peaks at about', options = '["940 nm, in the near infrared", "9.4 μm, in the infrared", "94 μm, in the microwave", "0.94 nm, in the X-ray region"]', why = 'By Wien''s law, λ_max = b ÷ T = 2.9 × 10⁻³ m K ÷ 310 K ≈ 9.4 × 10⁻⁶ m = 9.4 μm. This lies in the infrared. That is why the human body does not glow visibly but can be seen by infrared night-vision cameras.', wrong = '{"0": "940 nm is ten times too short, a power-of-ten slip. It would be the peak for a body at about 3100 K, not 310 K.", "2": "94 μm is ten times too long. It comes from a power-of-ten slip in the division.", "3": "A peak at 0.94 nm would need a temperature of about 3 million kelvin, nothing like body temperature."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-0413' AND answer = 1;
UPDATE questions SET stem = 'The book uses the uncertainty principle to argue that electrons cannot exist inside the nucleus. The reasoning is that confining an electron to about 10⁻¹⁴ m would', options = '["give it a negative mass", "give it zero energy", "give it an energy of the order of 100 MeV, far more than electrons in atoms are ever observed to have", "make it a proton"]', why = 'By the uncertainty principle Δx Δp ≈ h. Confining an electron to Δx ≈ 10⁻¹⁴ m gives Δp ≈ h/Δx ≈ 6.6 × 10⁻²⁰ kg m s⁻¹. For such a fast electron E ≈ pc ≈ 2 × 10⁻¹¹ J, about 120 MeV. Electrons in atoms never show energies anywhere near this, so electrons cannot exist inside the nucleus.', wrong = '{"0": "The uncertainty principle says nothing about negative mass. Mass is never negative.", "1": "Confining the electron makes its momentum and energy very large, not zero.", "3": "Confining an electron does not turn it into a proton. The argument is about the huge energy it would need."}', updated_at = unixepoch() * 1000 WHERE id = 'PHY-1613' AND answer = 2;
UPDATE questions SET stem = 'A prolonged PR interval on an ECG indicates', options = '["myocardial infarction", "first-degree heart block", "electrolyte disturbance", "ventricular tachycardia"]', why = 'The time from the start of atrial depolarization to the start of ventricular depolarization is normally about 0.12 to 0.20 s. If it is prolonged, the impulse is being delayed between the atria and ventricles, which indicates a first-degree heart block.', wrong = '{"0": "Myocardial infarction is shown by an elevated ST segment and hyper-acute T waves, not a long PR.", "2": "Electrolyte disturbance is suggested by T wave abnormalities.", "3": "Ventricular tachycardia shows up as abnormalities of the QRS complex."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1424' AND answer = 1;
UPDATE questions SET stem = 'Which ecological pyramid can never be inverted?', options = '["Pyramid of biomass", "Pyramid of energy", "Pyramid of numbers", "Age pyramid of a population"]', why = 'At each feeding level, much energy is lost as heat in respiration, so less energy passes to the next level. Each higher level therefore always has less energy than the one below, and the pyramid of energy can never be inverted. Pyramids of numbers and biomass can be inverted in some ecosystems.', wrong = '{"0": "A pyramid of biomass can be inverted, for example in some aquatic ecosystems.", "2": "A pyramid of numbers can be inverted, for example when one tree supports many insects.", "3": "An age pyramid shows the age groups in a population, not feeding levels. It can be narrow at the base when birth rates fall, so it is not always upright."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-7198' AND answer = 1;
UPDATE questions SET stem = 'Blood velocity is lowest in', options = '["the aorta", "the venae cavae", "capillaries", "arterioles"]', why = 'Blood flows fastest in the aorta, about 450 to 500 mm/s, and slows along the arteries and arterioles. It is slowest in the capillaries, below about 1 mm/s, which gives time for exchange with tissues. It then speeds up again in venules and veins, to about 250 to 300 mm/s in the venae cavae.', wrong = '{"0": "The aorta has the highest velocity, about 450 to 500 mm/s.", "1": "Velocity rises again in the venae cavae to about 250 to 300 mm/s.", "3": "Arterioles carry blood faster than capillaries, since velocity keeps falling until the capillaries."}', updated_at = unixepoch() * 1000 WHERE id = 'BIO-1438' AND answer = 2;
